"""Explain atomic set, generated operations and old/new return values."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1537': ('공용 숫자판을 새 숫자로 바꾸는 사람도, 숫자에 1을 더하는 사람도 같은 열쇠 규칙을 지켜야 합니다. 바꾸는 사람만 문을 무시하고 들어오면 더하는 중간에 끼어들 수 있기 때문입니다.', '값 교체도 읽기·더하기와 같은 잠금으로 보호되는 이유를 이해합니다.', '초기값 5에 set(10)과 add(2)를 차례로 놓으세요. set 먼저면 12, add 먼저면 10이 되는 두 순서를 비교하세요.', ['generic_atomic64_set은 atomic64 자료의 counter를 주어진 i로 바꿉니다. 예를 들어 i=10이면 기존 값이 무엇이든 이 연산에서 10을 저장합니다. 더하기가 아니라 새 값으로 교체하는 동작입니다.', '함수는 lock_addr(v)로 객체 주소에 맞는 잠금을 고릅니다. read와 add도 같은 객체에 같은 잠금을 쓰므로 한쪽이 보호 구간 안에 있을 때 다른 쪽이 그 갱신 중간에 들어오지 못합니다.', 'raw_spin_lock_irqsave로 잠금을 잡고 이전 인터럽트 상태를 저장한 다음 v->counter = i를 실행합니다. 이후 잠금을 풀고 인터럽트 상태를 복구합니다. counter를 직접 쓰는 무보호 대입과 이 API 호출은 다릅니다.', '원자성은 여러 호출의 실행 순서까지 미리 정해 주지는 않습니다. 초기 5에 set(10) 뒤 add(2)가 오면 12, add(2) 뒤 set(10)이 오면 10입니다. 각 연산이 쪼개지지 않아도 어떤 연산이 나중인가에 따라 결과가 달라집니다.', '이 generic 헤더는 arch_atomic64_set_release도 generic_atomic64_set으로 연결합니다. 이런 이름 연결을 alias라고 부릅니다. release는 메모리 접근의 공개 순서와 관련된 API 약속입니다. 여기서는 그 이름이 어느 본체로 이어지는지 확인하는 것이 핵심입니다.', '다른 CPU용 구현은 다른 명령을 쓸 수 있습니다. 따라서 이 구현에 잠금이 있다는 사실만으로 모든 공개 atomic API가 같은 강한 순서를 보장한다고 기대하면 안 됩니다. 사용하는 API가 약속하는 원자성과 메모리 순서에 맞춰 코드를 작성해야 합니다.'], [('같은 객체의 set과 add는 서로 상관없는 잠금을 쓰나요?', ['네. set은 언제나 잠금 없이 바로 써요', '아니요. 둘 다 lock_addr(v)로 같은 잠금을 골라요'], 'set의 대입도 irqsave 잠금과 irqrestore 사이에 있습니다. 같은 객체에 참여하는 연산들이 동일한 보호 규칙을 지켜야 중간에 끼어들지 못해요.'), ('이 generic 헤더에서 arch_atomic64_set_release는 무엇으로 연결되나요?', ['generic_atomic64_set이에요', '별도의 잠금 없는 volatile 대입이에요'], '헤더의 #define이 generic_atomic64_set을 가리킵니다. 이름의 연결과 실제 본체를 함께 읽으세요. 이 특정 구현의 연결을 모든 아키텍처의 코드라고 일반화하면 안 됩니다.')]), 'os1538': ('같은 양식의 안내문에서 제목과 행동만 바꾸어 여러 안내문을 만들 수 있습니다. 코드도 잠금 틀은 그대로 두고 add와 += 같은 재료를 넣어 여러 함수를 만들 수 있습니다.', '매크로의 이름 붙이기와 실행 중 숫자 계산을 구별합니다.', 'ATOMIC64_OP(add, +=)에서 op는 add, c_op는 +=로 바꾸세요. 함수 이름 generic_atomic64_add와 본문 counter += a를 적으세요.', ['ATOMIC64_OP(op, c_op)는 함수를 만드는 코드 양식입니다. 매크로는 프로그램 실행 전에 전처리 단계에서 코드 조각을 바꾸는 규칙입니다. op와 c_op는 이 양식에 넣는 재료입니다.', 'generic_atomic64_##op에서 ##는 코드 토큰을 붙입니다. op에 add를 넣으면 generic_atomic64_add라는 함수 이름이 됩니다. 토큰은 코드를 이루는 이름이나 기호 같은 단위입니다. ##가 실행 중 두 숫자를 더하는 것은 아닙니다.', 'c_op에 +=를 넣으면 본문의 v->counter c_op a가 v->counter += a가 됩니다. +=는 원래 값에 a를 더해 그 자리에 저장하라는 뜻입니다. 초기 5에 a=2라면 저장된 값은 7입니다.', '생성된 함수는 주소로 잠금을 고르고, 잠금을 잡고 계산한 뒤 풉니다. 읽기와 계산·쓰기 전체가 같은 보호 구간에 있으므로 read와 set을 따로 부르는 증가와 다릅니다. 이 묶음을 RMW, 읽기·수정·쓰기 연산이라고 부릅니다.', '이 양식의 반환형은 void입니다. 값은 바꾸지만 호출자에게 결과 숫자를 돌려주지 않습니다. void가 아무 일도 안 한다는 뜻은 아닙니다. 결과 숫자가 필요하면 갱신 후 값을 주는 return 변형이나 갱신 전 값을 주는 fetch 변형의 약속을 확인하세요.', '같은 틀을 add와 sub뿐 아니라 and, or, xor에도 씁니다. 이 셋은 각 비트 자리를 다루는 연산입니다. 비트는 0 또는 1인 자리이고 AND는 둘 다 1일 때, OR는 하나라도 1일 때, XOR는 서로 다를 때 1입니다. 이름 생성과 실제 계산 기호를 각각 연결해 읽으세요.'], [('ATOMIC64_OP(add, +=)로 만든 함수는 어떤 결과 형식을 가지나요?', ['언제나 증가 후 s64 숫자를 돌려줘요', 'void라서 결과 숫자는 돌려주지 않아요'], '함수 정의 앞에 void가 적혀 있습니다. counter는 갱신하지만 반환 숫자는 없어요. 저장된 값을 바꾸는 것과 호출자에게 숫자를 주는 것을 구별하세요.'), ('generic_atomic64_##op의 ##는 무슨 일을 하나요?', ['전처리 단계에서 함수 이름의 토큰을 붙여요', '실행 중 두 counter의 숫자를 더해요'], 'op가 add이면 함수 이름이 generic_atomic64_add가 됩니다. 실제 숫자 덧셈은 본문에 넣은 +=가 수행해요. 이름을 만드는 시점과 계산하는 시점이 다릅니다.')]), 'os1539': ('숫자판에 5가 있고 2를 더한 뒤 “내가 만든 값은 7”이라고 영수증을 준다고 해 봅시다. 다음 사람이 숫자판을 8로 바꿔도 내 영수증에는 7이 남습니다.', '갱신 후 반환값과 이후 바뀔 수 있는 저장 값을 구별합니다.', 'counter=5 → 2 더해 counter=7 → val=7 → 잠금 풀기 → 7 반환을 그리세요. 잠금이 풀린 뒤 다른 작업이 8로 바꾸는 화살표도 추가하세요.', ['ATOMIC64_OP_RETURN은 계산한 뒤의 값을 돌려주는 함수 양식입니다. add_return은 더한 뒤 값을, sub_return은 뺀 뒤 값을 반환합니다. 같은 덧셈이어도 fetch_add와 반환 기준이 다릅니다.', '핵심 문장은 val = (v->counter c_op a)입니다. add라면 c_op는 +=입니다. 복합 대입 counter += a는 값을 갱신하고 그 갱신된 값을 표현식 결과로 가집니다. 그 결과를 지역 변수 val에 담습니다.', '초기값 5에서 a=2라면 counter가 7로 바뀌고 val도 7입니다. 잠금을 잡은 상태에서 계산과 결과 보관을 함께 합니다. 이전 값 5를 반환하려는 코드가 아닙니다.', '이후 raw_spin_unlock_irqrestore로 잠금을 풀고 return val을 실행합니다. counter를 다시 읽는 명령은 없습니다. 잠금 안에서 보관한 이 호출의 결과를 돌려줍니다.', '잠금이 풀린 뒤 다른 CPU가 counter를 8로 바꿔도 이 호출이 보관한 val은 7입니다. 반환이 늦어지면 원본은 이미 8인데 나는 7을 받을 수도 있습니다. 이것은 잘못된 원자 연산이 아니라 각 호출 결과와 현재 상태의 차이입니다.', '반환한 숫자를 현재 원본을 계속 예약하는 권리로 생각하지 마세요. 다른 값과 함께 판단하거나 조건에 따라 다음 갱신을 해야 한다면 그 전체 과정에 맞는 동기화가 필요합니다. 어느 시점의 숫자가 필요한지 먼저 정하면 return과 fetch를 구별하기 쉽습니다.'], [('초기값 5에 add_return으로 2를 더하면 어떤 값을 돌려주나요?', ['갱신 전 값 5예요', '갱신 후 값 7이에요'], '5+2=7을 저장하고 그 결과를 val에 보관합니다. add_return은 이후 값, fetch_add는 이전 값이라는 차이가 있어요. 이 문제에서는 7을 반환합니다.'), ('잠금을 푼 뒤 counter를 다시 읽어 다른 작업의 변경까지 포함하나요?', ['아니요. 이미 보관한 지역 val을 반환해요', '네. 반환 직전에 언제나 최신 원본을 다시 읽어요'], '본문의 마지막은 return val입니다. 잠금을 푼 뒤 원본이 바뀌어도 지역 복사본은 그대로예요. 호출 결과가 원본의 영구적인 최신 값이라는 뜻은 아닙니다.')]), 'os1540': ('번호표 기계가 현재 번호 5를 손님에게 주고 다음 번호를 7로 바꾼다고 해 봅시다. 손님에게 준 번호와 기계에 새로 저장한 번호가 서로 다를 수 있습니다.', '갱신 전 값을 반환하는 fetch 연산의 복사·수정 순서를 이해합니다.', 'counter=5 → val에 5 복사 → counter에 2 더해 7 → 5 반환을 적으세요. add_return과 다른 부분에 동그라미를 치세요.', ['fetch_add는 값을 더하면서 더하기 전 값을 돌려줍니다. fetch_sub도 빼기 전 값을 반환하고 비트 fetch 연산들도 갱신 전 값이라는 같은 기준을 사용합니다. fetch는 여기서 이전 값을 가져오는 동작과 갱신이 묶였다는 뜻입니다.', 'ATOMIC64_FETCH_OP가 만든 함수는 잠금을 잡은 뒤 val = v->counter를 먼저 실행합니다. 초기값 5라면 지역 변수 val에 5가 담깁니다. 아직 이 줄에서는 원본 숫자를 바꾸지 않았습니다.', '그다음 v->counter c_op a를 실행합니다. add에 a=2라면 원본은 7로 바뀝니다. 잠금을 푼 뒤 return val이 돌려주는 값은 5입니다. 따라서 반환 5와 저장 7을 서로 바꾸어 읽으면 안 됩니다.', '이전 값 복사와 갱신은 같은 잠금 구간입니다. 다른 참여 연산이 두 문장 사이에 같은 counter를 바꿀 수 없습니다. read로 읽고 잠금을 풀었다가 나중에 set하는 방식과 다른 점입니다.', '초기 5에서 두 작업이 각각 fetch_add(1)을 하면 한쪽은 이전 값 5, 다음 쪽은 6을 받고 저장 값은 7이 됩니다. 어느 작업이 먼저인지는 다를 수 있지만 그 두 증가 사이에 같은 이전 번호를 중복으로 읽어 버리는 방식은 아닙니다.', '이 성질을 번호 발급 등에 활용할 수 있지만 숫자가 표현 범위를 넘거나 다른 코드가 값을 재설정하면 번호를 영원히 중복 없이 준다고 보장할 수 없습니다. 값 범위와 재사용 기간도 설계해야 합니다. 이번 수업에서는 작은 수에서 이전 값 확보와 갱신이 하나로 묶이는 원리를 확인합니다.'], [('초기값 5에 fetch_add(2)를 하면 반환값과 저장값은?', ['반환 7, 저장 5예요', '반환 5, 저장 7이에요'], '먼저 5를 val에 복사하고 원본에 2를 더해 7로 만듭니다. 마지막에 돌려주는 것은 val의 5예요. 두 문장 순서를 따라가면 return 변형과 구별할 수 있습니다.'), ('이전 값 복사와 증가는 같은 잠금 구간 안에 있나요?', ['네. 한 번 잡은 잠금 안에서 둘 다 해요', '아니요. 이전 값은 잠금 없이 미리 읽어요'], 'raw 잠금을 잡은 뒤 val을 복사하고 counter를 갱신한 다음 풉니다. 그래서 둘 사이에 다른 참여 연산이 끼어들지 못해요. 별도 read와 set의 조합과 다릅니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_380.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
